parameters.old_string:
query = """
MATCH (start:UndergroundStation {name: 'Hammersmith'})
CALL gds.spanningTree.stream({
    nodeProjection: 'UndergroundStation',
    relationshipProjection: {
        LINK: {
            type: 'LINK',
            properties: 'time'
        }
    },
    sourceNode: start,
    relationshipWeightProperty: 'time'
})
YIELD nodeId, parentId, weight
WITH gds.util.asNode(nodeId) AS node, gds.util.asNode(parentId) AS parent, weight
WHERE parent IS NOT NULL
RETURN node.name AS nodeName, parent.name AS parentName, weight
ORDER BY nodeName
"""

